package main

import "fmt"

// MinStack is a stack that also knows its smallest value.
type MinStack struct {
	values []int
	mins   []int
}

func (s *MinStack) push(x int) {
	smallest := x
	if len(s.mins) > 0 && s.mins[len(s.mins)-1] < x {
		smallest = s.mins[len(s.mins)-1]
	}
	s.values = append(s.values, x)
	s.mins = append(s.mins, smallest)
}

func (s *MinStack) pop() {
	s.values = s.values[:len(s.values)-1]
	s.mins = s.mins[:len(s.mins)-1]
}

func (s *MinStack) top() int {
	return s.values[len(s.values)-1]
}

func (s *MinStack) getMin() int {
	return s.mins[len(s.mins)-1]
}

func main() {
	var q int
	fmt.Scan(&q)
	stack := MinStack{}
	for i := 0; i < q; i++ {
		var op string
		fmt.Scan(&op)
		switch op {
		case "push":
			var x int
			fmt.Scan(&x)
			stack.push(x)
		case "pop":
			stack.pop()
		case "top":
			fmt.Println(stack.top())
		case "getMin":
			fmt.Println(stack.getMin())
		}
	}
}

